import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"DHCP 指纹检测机制与原理","description":"","frontmatter":{"title":"DHCP 指纹检测机制与原理"},"headers":[],"relativePath":"traditional/DHCP.md","filePath":"traditional/DHCP.md"}`),a={name:`traditional/DHCP.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="🏷️-dhcp-指纹检测原理" tabindex="-1">🏷️ DHCP 指纹检测原理 <a class="header-anchor" href="#🏷️-dhcp-指纹检测原理" aria-label="Permalink to “🏷️ DHCP 指纹检测原理”">​</a></h1><p><strong>DHCP 指纹检测</strong>属于应用层与网络配置协议层的终端指纹识别技术，无需解密 HTTPS 流量即可精准识别终端操作系统类型。</p><h2 id="❓-什么是-dhcp-指纹" tabindex="-1">❓ 什么是 DHCP 指纹 <a class="header-anchor" href="#❓-什么是-dhcp-指纹" aria-label="Permalink to “❓ 什么是 DHCP 指纹”">​</a></h2><p>DHCP（Dynamic Host Configuration Protocol，动态主机配置协议）用于为局域网内的终端设备动态分配 IP 地址及网络参数。在客户端向 DHCP 服务器发送请求时，会在报文中附带多个配置选项（Options）。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>不同操作系统在实现 DHCP 客户端时，请求的 Option 编号顺序（Option 55）、厂商标识（Option 60）以及客户端标识（Option 61）存在固定的行为习惯，这些选项组合构成了独一无二的“DHCP 指纹”。</p></div><h3 id="📑-常见操作系统的-dhcp-指纹特征" tabindex="-1">📑 常见操作系统的 DHCP 指纹特征 <a class="header-anchor" href="#📑-常见操作系统的-dhcp-指纹特征" aria-label="Permalink to “📑 常见操作系统的 DHCP 指纹特征”">​</a></h3><p>校园网 DHCP 服务器或探针根据请求报文中的 Option 特征判断客户端类型：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统类型</th><th style="text-align:left;">Option 55 请求参数序列 (Prl)</th><th style="text-align:left;">Option 60 厂商标识特征 (Vendor Class ID)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 10/11</strong></td><td style="text-align:left;"><code>1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252, 114</code></td><td style="text-align:left;"><code>MSFT 5.0</code></td></tr><tr><td style="text-align:left;"><strong>现代 Android</strong></td><td style="text-align:left;"><code>1, 3, 6, 15, 26, 28, 51, 58, 59, 43, 114, 108</code></td><td style="text-align:left;"><code>android-dhcp-&lt;版本号&gt;</code></td></tr><tr><td style="text-align:left;"><strong>现代 iOS</strong></td><td style="text-align:left;"><code>1, 121, 3, 6, 15, 108, 114, 119, 252</code></td><td style="text-align:left;">通常为空</td></tr><tr><td style="text-align:left;"><strong>现代 macOS</strong></td><td style="text-align:left;"><code>1, 3, 6, 15, 108, 114, 119</code></td><td style="text-align:left;">通常为空</td></tr><tr><td style="text-align:left;"><strong>现代发行版Linux / BusyBox OpenWrt</strong></td><td style="text-align:left;"><code>1, 3, 6, 12, 15, 28, 51, 58</code> / <code>1, 3, 6, 15, 28, 51, 12</code></td><td style="text-align:left;">通常为空 / <code>udhcp &lt;版本号&gt;</code></td></tr></tbody></table><h2 id="🔬-校园网检测-dhcp-指纹的原理" tabindex="-1">🔬 校园网检测 DHCP 指纹的原理 <a class="header-anchor" href="#🔬-校园网检测-dhcp-指纹的原理" aria-label="Permalink to “🔬 校园网检测 DHCP 指纹的原理”">​</a></h2><p>校园网 DHCP 服务器或出口网关通过对 UDP 67/68 端口的 <code>DHCP Request</code> 报文进行抓包与解析，提取指纹并与系统基准库比对。</p><h3 id="_1-正常直连-未挂载路由器" tabindex="-1">1. 正常直连（未挂载路由器） <a class="header-anchor" href="#_1-正常直连-未挂载路由器" aria-label="Permalink to “1. 正常直连（未挂载路由器）”">​</a></h3><p>单台终端直接连接校园网发起 DHCP 地址请求时，DHCP 指纹与后续网络流量的协议栈特征保持一致。</p><table tabindex="0"><thead><tr><th style="text-align:left;">设备类型</th><th style="text-align:left;">请求流量类型</th><th style="text-align:left;">抓取的 DHCP 指纹</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 电脑</strong></td><td style="text-align:left;">DHCP Request</td><td style="text-align:left;"><code>Option 55</code> 含 249/252/114，<code>Option 60</code> 为 <code>MSFT 5.0</code></td><td style="text-align:left;">唯一设备（Windows）</td></tr><tr><td style="text-align:left;"><strong>Android 手机</strong></td><td style="text-align:left;">DHCP Request</td><td style="text-align:left;"><code>Option 55</code> 含 26/28/58/59，<code>Option 60</code> 含 <code>android</code></td><td style="text-align:left;">唯一设备（Android）</td></tr></tbody></table><h3 id="_2-挂载路由器-经过路由-nat-转发" tabindex="-1">2. 挂载路由器（经过路由 NAT 转发） <a class="header-anchor" href="#_2-挂载路由器-经过路由-nat-转发" aria-label="Permalink to “2. 挂载路由器（经过路由 NAT 转发）”">​</a></h3><p>宿舍接入路由器后，路由器 WAN 口向校园网请求 IP 地址，此时发出的是路由器自身系统的 DHCP 指纹；而下挂设备流量经 NAT 转发后访问外网，网关会对比 DHCP 记录与实际流量特征。</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景与设备组合</th><th style="text-align:left;">抓取的网络特征组合</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OpenWrt 路由器 WAN 口申请 IP</strong></td><td style="text-align:left;">DHCP 指纹为 <code>Linux/udhcpc</code></td><td style="text-align:left;">⚠️ <strong>识别为路由器设备</strong></td></tr><tr><td style="text-align:left;"><strong>路由 WAN 口 + 下挂 Windows</strong></td><td style="text-align:left;">DHCP 指纹为 <code>Linux/udhcpc</code>，而上报 HTTP UA 为 <code>Windows NT 10.0</code></td><td style="text-align:left;">⚠️ <strong>协议栈指纹冲突，判定挂载路由</strong></td></tr></tbody></table>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};